const API_BASE = 'https://jsonplaceholder.typicode.com'

export interface Post {
  id: number
  userId: number
  title: string
  body: string
}

export interface PostComment {
  id: number
  postId: number
  name: string
  email: string
  body: string
}

/**
 * Uncached read, equivalent to the old `getServerSideProps` behavior: the data
 * is fetched from the source on every request.
 */
export async function getRecentPosts(limit = 5): Promise<Post[]> {
  const res = await fetch(`${API_BASE}/posts?_limit=${limit}`, {
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch recent posts (${res.status})`)
  }

  return res.json()
}

/**
 * Cached read revalidated every 60 seconds, equivalent to the old
 * `getStaticProps` + `revalidate: 60` (ISR).
 */
export async function getPosts(): Promise<Post[]> {
  const res = await fetch(`${API_BASE}/posts`, {
    next: { revalidate: 60 },
  })

  if (!res.ok) {
    throw new Error(`Failed to fetch posts (${res.status})`)
  }

  return res.json()
}

/**
 * Cached read revalidated every 5 minutes, equivalent to the old
 * `getStaticProps` + `revalidate: 300`. Returns `null` when the post does not
 * exist so callers can render the not-found UI.
 */
export async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`${API_BASE}/posts/${id}`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return null
  }

  const post: Post | Record<string, never> = await res.json()

  // The upstream API answers unknown ids with an empty object.
  return 'id' in post ? post : null
}

export async function getPostComments(id: string): Promise<PostComment[]> {
  const res = await fetch(`${API_BASE}/posts/${id}/comments`, {
    next: { revalidate: 300 },
  })

  if (!res.ok) {
    return []
  }

  return res.json()
}

