                <Link href="/blog">Blog</Link>
              </nav>
            </header>
            <main>{children}</main>
            <footer>
              <p>&copy; 2024 My Blog</p>
            </footer>
          </div>
        </AppProvider>
      </body>
    </html>
  )
}

