import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { getPost, getPostComments, getPosts } from '@/lib/posts'
import { BackButton } from './back-button'

// Replaces `fallback: 'blocking'`: ids that were not prerendered by
// `generateStaticParams` are rendered on demand and then cached.
export const dynamicParams = true

// Replaces `getStaticPaths`.
export async function generateStaticParams() {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

// Replaces the `<Head>` tags that used to be rendered by the page component.
export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) {
    return { title: 'Post Not Found' }
  }

  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getPost(id),
    getPostComments(id),
  ])

  // Replaces `return { notFound: true }` from `getStaticProps`.
  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

