'use client' // Error boundaries must be Client Components

import { useEffect } from 'react'

// Replaces `pages/_error.js` for errors thrown below the root layout. There is
// no `statusCode` prop any more: a rendering error is always reported through
// the `error` object, and `retry()` re-renders the boundary's children.
export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => retry()}>Try again</button>
    </div>
  )
}

