'use client' // Error boundaries must be Client Components

import { useEffect } from 'react'

// Handles errors thrown by the root layout itself, which `app/error.tsx` cannot
// catch. It replaces the root layout, so it renders its own document. Metadata
// exports are not supported in Client Components, so the title is set with
// React's `<title>` component.
export default function GlobalError({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <html lang="en">
      <body>
        <title>Error</title>
        <div className="error-page">
          <h1>An error occurred</h1>
          <p>Sorry, something went wrong.</p>
          <button onClick={() => retry()}>Try again</button>
        </div>
      </body>
    </html>
  )
}

