import type { NextRequest } from 'next/server'

export interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface CreatePostBody {
  title?: unknown
  content?: unknown
}

export async function GET() {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: NextRequest) {
  // The Pages Router parsed `req.body` for us; Route Handlers use the Web
  // `Request` API instead.
  let body: CreatePostBody
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  if (typeof title !== 'string' || !title || typeof content !== 'string' || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

// Methods that are not exported are answered by Next.js with a 405 and the
// appropriate `Allow` header, so the manual fallback is no longer needed.

